CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE TABLE public.game_saves (user_id uuid PRIMARY KEY, state jsonb NOT NULL DEFAULT '{"cases":{},"xp":0,"hints":3,"flawless":[],"encounters":{}}'::jsonb, revision integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.game_saves TO authenticated;
GRANT ALL ON public.game_saves TO service_role;
ALTER TABLE public.game_saves ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own progress" ON public.game_saves FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.case_settings (case_id text PRIMARY KEY, title text, summary text, difficulty text, status text NOT NULL DEFAULT 'published' CHECK (status IN ('published','draft')), reward_xp integer CHECK (reward_xp BETWEEN 0 AND 1000), sort_order integer CHECK (sort_order BETWEEN 1 AND 3), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.case_settings TO anon;
GRANT SELECT, INSERT, UPDATE ON public.case_settings TO authenticated;
GRANT ALL ON public.case_settings TO service_role;
ALTER TABLE public.case_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public case settings" ON public.case_settings FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Admins create settings" ON public.case_settings FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update settings" ON public.case_settings FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));